const detection = {
    label: msg.payload.label,
    text_th: msg.payload.text_th,
    confidence: msg.payload.confidence,
    timestamp: msg.payload.timestamp
};
flow.set('last_detection', detection);

const imgbbKey = env.get('IMGBB_API_KEY');
if (!imgbbKey) {
    node.error('ไม่พบ IMGBB_API_KEY ใน environment variable');
    return null;
}

const params = new URLSearchParams();
params.append('key', imgbbKey);
params.append('image', msg.payload.image_base64);

msg.headers = { 'content-type': 'application/x-www-form-urlencoded' };
msg.payload = params.toString();
return msg;

const detection = flow.get('last_detection') || {};
const imageUrl = (msg.payload && msg.payload.data && msg.payload.data.url) ? msg.payload.data.url : null;

const text = `${detection.text_th}\nเวลา: ${detection.timestamp}`;

const messages = [{ type: 'text', text: text }];
if (imageUrl) {
    messages.push({
        type: 'image',
        originalContentUrl: imageUrl,
        previewImageUrl: imageUrl
    });
}

const token = env.get('LINE_CHANNEL_ACCESS_TOKEN');
const userId = env.get('LINE_USER_ID');
if (!token || !userId) {
    node.error('ไม่พบ LINE_CHANNEL_ACCESS_TOKEN หรือ LINE_USER_ID ใน environment variable');
    return null;
}

msg.headers = {
    'content-type': 'application/json',
    'Authorization': `Bearer ${token}`
};
msg.payload = {
    to: userId,
    messages: messages
};
return msg;

const detection = flow.get('last_detection') || {};
const imageUrl = (msg.payload && msg.payload.data && msg.payload.data.url) ? msg.payload.data.url : null;

msg.topic = "INSERT INTO detections (label, text_th, confidence, image_url) VALUES ($label, $text_th, $confidence, $image_url)";
msg.payload = [detection.label, detection.text_th, detection.confidence, imageUrl];
return msg;

const detection = flow.get('last_detection') || {};
const imageUrl = (msg.payload && msg.payload.data && msg.payload.data.url) ? msg.payload.data.url : null;

const grafanaUrl = env.get('GRAFANA_URL');
const grafanaToken = env.get('GRAFANA_API_KEY');
if (!grafanaUrl || !grafanaToken) {
    node.error('ไม่พบ GRAFANA_URL หรือ GRAFANA_API_KEY ใน environment variable');
    return null;
}

let text = detection.text_th || detection.label;
if (imageUrl) {
    text += ` — รูปภาพ: ${imageUrl}`;
}

msg.url = `${grafanaUrl}/api/annotations`;
msg.headers = {
    'content-type': 'application/json',
    'Authorization': `Bearer ${grafanaToken}`
};
msg.payload = {
    text: text,
    tags: ['camera-detector', detection.label],
    time: Date.now()
};
return msg;

const p = msg.payload;
const pct = Math.round((p.confidence || 0) * 100);
msg.payload = `${p.text_th}\n${p.timestamp} (${pct}%)`;
msg.topic = p.label;
return msg;

const p = msg.payload;
msg.payload = {
    img: `data:image/jpeg;base64,${p.image_base64}`,
    caption: `${p.text_th} — ${p.timestamp}`
};
return msg;
